    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        _isLoading = true;
        _errorMessage = null;
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _isLoading = false;
        }
    }

